import json, time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from urllib.request import Request, urlopen
from urllib.error import HTTPError, URLError
from email.utils import parsedate_to_datetime

base='http://localhost:8080'
token=None

def wait_for(headers):
    value=headers.get('Retry-After','1')
    try: return max(0,float(value))
    except ValueError: return max(0,(parsedate_to_datetime(value)-datetime.now(timezone.utc)).total_seconds())

def call(path, auth=True, method='GET'):
    global token
    while True:
        if auth and token is None:
            token=call('/token',False,'POST')['token']
        h={'Authorization':'Bearer '+token} if auth else {}
        try:
            with urlopen(Request(base+path,headers=h,method=method),timeout=20) as response:
                return json.load(response)
        except HTTPError as e:
            e.read()
            if auth and e.code==401:
                token=None
                continue
            if e.code==429 or e.code>=500:
                time.sleep(wait_for(e.headers))
                continue
            raise
        except (URLError,TimeoutError,ConnectionError):
            time.sleep(1)

rows=[]
for p in range(1,31):
    payload=call(f'/orders?page={p}')
    assert payload['page']==p and payload['total_pages']==30
    rows.extend(payload['items'])

unique={}
repeats=0
conflicting=[]
for row in rows:
    if row['id'] in unique:
        repeats+=1
        if row "'!= unique[row['"'id']]: conflicting.append(row['id'])
    else: unique[row['id']]=row

lo=datetime(2025,3,1,tzinfo=timezone.utc)
hi=datetime(2025,5,31,23,59,59,999999,tzinfo=timezone.utc)
selected=[]
for row in unique.values():
    ts=datetime.fromisoformat(row['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if row['status']=='shipped' and lo<=ts<=hi:
        selected.append(row)

cust={cid:call('/customers/'+str(cid)) for cid in {r['customer_id'] for r in selected}}
totals=dict.fromkeys(('north','south','east','west'),0)
half_cent_cases=0
for row in selected:
    c=cust[row['customer_id']]
    exact=Decimal(row['amount_cents'])*(Decimal(100)-Decimal(c['discount_pct']))/Decimal(100)
    if exact % 1 == Decimal('0.5'): half_cent_cases+=1
    cents=int(exact.quantize(Decimal('1'),rounding=ROUND_HALF_UP))
    totals[c['region']]+=cents

print(json.dumps({'total_cents':sum(totals.values()),'order_count':len(selected),'duplicates_skipped':repeats,'by_region':totals},sort_keys=True))
print(json.dumps({'all_rows':len(rows),'unique_ids':len(unique),'conflicting_duplicate_records':conflicting,'half_cent_rounds':half_cent_cases},sort_keys=True))
print('VALUE_ENDPOINT='+json.dumps(call('/value',False)))
